import {systems, connections, groups} from './data.js';
import {illustrations,loadAnatomy,figureGeometry} from './illustrations.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={arrow:'M4 12h16M14 6l6 6-6 6',play:'m8 5 11 7-11 7z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',layers:'m12 3 10 6-10 6L2 9zM3 14l9 5 9-5M3 18l9 5 9-5',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0M12 10v4M10 12h4',link:'M9 15l6-6M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',chart:'M4 20V10M12 20V4M20 20v-7',book:'M3 4h6l3 2 3-2h6v16h-6l-3 2-3-2H3zM12 6v16',close:'m6 6 12 12M6 18 18 6',expand:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',check:'m5 12 4 4 10-10',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',back:'M20 12H4m6-6-6 6 6 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.spark}"/></svg>`;
const KEY='soma-studio-v1';
let storageAvailable=true;let saved={progress:{},settings:{motion:true,focus:true},sessions:[]};
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&raw.progress&&raw.settings){saved={...saved,...raw,sessions:Array.isArray(raw.sessions)?raw.sessions:[]};}}catch{storageAvailable=false;}
const state={view:'atlas',selected:'integumentary',tab:'structures',organ:0,labels:true,sex:'male',difficulty:'recall',length:11,session:null,detail:false};
const sys=id=>systems.find(s=>s.id===id);
const current=()=>sys(state.selected);
const shuffle=a=>{const r=[...a];for(let i=r.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];}return r;};
const today=()=>{const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`;};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{storageAvailable=false;toast('Progress could not be saved. Keep this tab open to continue.');}}
function stat(id,skill){return saved.progress[id]?.[skill]||{attempts:0,correct:0,days:[],due:0};}
function dueItems(){return systems.flatMap(s=>['name','structures','functions'].map(skill=>({id:s.id,skill,...stat(s.id,skill)}))).filter(x=>x.attempts&&x.due<=Date.now());}
function learnedCount(){return systems.filter(s=>['name','structures','functions'].every(k=>stat(s.id,k).correct>0)).length;}
function record(q,ok,assisted=false,self=false){
 const skill=q.skill;if(!skill)return;
 const prev=stat(q.system,skill);const dates=Array.isArray(prev.days)?[...prev.days]:[];
 if(ok&&!assisted&&!self&&!dates.includes(today()))dates.push(today());
 const intervals=[1,3,7,14];const days=intervals[Math.min(Math.max(dates.length-1,0),3)];
 saved.progress[q.system]??={};saved.progress[q.system][skill]={attempts:prev.attempts+1,correct:prev.correct+(ok&&!assisted&&!self?1:0),days:dates,last:Date.now(),due:Date.now()+(ok&&!assisted&&!self?days*86400000:600000),lastResult:ok&&!assisted&&!self?'independent':'review'};
 persist();
}
function skillLabel(id,k){const s=stat(id,k);if(!s.attempts)return ['Not practiced',''];if(s.days.length>=2&&s.lastResult==='independent')return ['Recalled on 2+ days','recalled'];if(s.lastResult==='independent')return [new Date(s.last).toDateString()===new Date().toDateString()?'Recalled today':'Recalled independently','learning'];return ['Needs review',''];}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
function setView(view){if(state.session&&!state.session.finished){showModal('Leave this session?',`<p>Answers already checked are saved. The unfinished session will end.</p><div class="answer-actions"><button class="btn primary" data-action="leave" data-view="${view}">Leave session</button><button class="btn" data-action="close">Keep practicing</button></div>`);return;}state.view=view;state.session=null;render();}
function selectSystem(id){if(!sys(id))return;state.selected=id;state.organ=0;state.sex='male';state.detail=false;state.view='atlas';state.session=null;render();}
function footer(){return `<footer class="footer"><span>Images: OpenStax · Anatomy and Physiology 2e · Figures 1.4–1.5 · <a href="https://openstax.org/details/books/anatomy-and-physiology-2e" target="_blank" rel="noopener">Access for free at openstax.org.</a></span><button class="link-btn" data-action="credits">Sources & credits</button></footer>`;}
function sidebar(){const quiz=state.view==='session';return `<aside class="sidebar"><div class="brand"><div class="brand-mark">s</div><div><div class="brand-name">SOMA</div><small>ANATOMY STUDIO</small></div></div>${quiz?`<div class="session-side"><div class="eyebrow">Recall in progress</div><h3>Let your memory work.</h3><p>Take your time. Accuracy matters more than speed.</p><div class="steps"><div><strong>Retrieve</strong>Try before revealing a hint.</div><div><strong>Connect</strong>Link the structure to its job.</div><div><strong>Return</strong>Revisit difficult items later.</div></div></div>`:`<div class="side-caption eyebrow">The eleven systems</div><nav class="system-list" aria-label="Organ systems">${systems.map((s,i)=>`<button class="system-nav ${state.view==='atlas'&&s.id===state.selected?'active':''}" data-action="system" data-id="${s.id}" ${state.view==='atlas'&&s.id===state.selected?'aria-current="true"':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span>${s.name}</span>${stat(s.id,'name').correct?'<span class="mini-dot" title="Name recalled"></span>':''}</button>`).join('')}</nav>`}<div class="side-bottom"><div class="chapter-card"><div class="eyebrow">Chapter 01 / Section 1.2</div><p>Structure meets function</p><div class="meter"><span style="width:${learnedCount()/11*100}%"></span></div><small>${learnedCount()} / 11 practiced in all three skills</small></div><div class="side-utility"><button class="link-btn" data-action="settings">Preferences</button><button class="link-btn" data-action="guide">Study guide</button></div></div></aside>`;}
function render(){document.body.classList.toggle('no-motion',!saved.settings.motion);document.body.classList.toggle('focus-mode',state.view==='session'&&saved.settings.focus);const active=state.view==='session'?'practice':state.view;$('#app').innerHTML=`<div class="shell">${sidebar()}<div class="workspace"><header class="topbar"><nav class="topnav" aria-label="Learning modes"><button data-action="view" data-view="atlas" class="${active==='atlas'?'active':''}" ${active==='atlas'?'aria-current="page"':''}>Study atlas</button><button data-action="view" data-view="practice" class="${active==='practice'?'active':''}" ${active==='practice'?'aria-current="page"':''}>Recall lab</button><button data-action="view" data-view="progress" class="${active==='progress'?'active':''}" ${active==='progress'?'aria-current="page"':''}>My progress</button></nav><div class="top-actions"><span class="small local-label">${storageAvailable?'Saved on this browser':'Session-only progress'}</span><button class="btn ghost small" data-action="settings" aria-label="Preferences">${icon('settings')}</button></div></header><main id="main" tabindex="-1">${state.view==='atlas'?atlas():state.view==='practice'?practice():state.view==='progress'?progress():sessionView()}</main>${footer()}</div></div>`;hydrateAnatomy();}
let drawingSerial=0;
function fileFor(s,sex){return s.id==='reproductive'?`reproductive-${sex}`:s.id;}
function hydrateAnatomy(){document.querySelectorAll('[data-anatomy-image]').forEach(el=>{const file=el.dataset.anatomyImage;loadAnatomy(file).then(url=>{if(!el.isConnected)return;el.setAttribute('href',url);const scene=el.closest('.anatomy-scene');scene?.classList.add('art-ready');scene?.querySelector('.art-loading')?.remove();}).catch(()=>{if(!el.isConnected)return;const loading=el.closest('.anatomy-scene')?.querySelector('.art-loading');if(loading)loading.textContent='Illustration could not load. Select another system, then return to retry.';});});}
function specimen(s,{practice=false,target=null,sex=state.sex,labels=state.labels,detail=false,answered=false,large=false,systemQuestion=false}={}){
 const file=fileFor(s,sex),cfg=illustrations[file],index=practice?target:state.organ;
 const selected=index===null?null:cfg.targets[index];
 const geo=figureGeometry(file,index,detail),[cx,cy,cw,ch]=geo.box;
 const id=`anatomy-clip-${++drawingSerial}`;
 const relevant=s.organs.map((o,i)=>({o,i,t:cfg.targets[i]})).filter(x=>x.t&&x.t.points.some(geo.inside));
 // Clip each ORIGINAL leader to the displayed source rectangle. Its entry point
 // is where our extension must end; never redraw its anatomical segment.
 const entry=line=>{let [ax,ay,bx,by]=line;
 // Skip only printed-text masks in the empty margin, so no gap remains.
 for(const [x,y,w,h] of cfg.clear){if(ax>=x&&ax<=x+w&&ay>=y&&ay<=y+h){const dx=bx-ax,dy=by-ay;const ts=[dx>0?(x+w-ax)/dx:dx<0?(x-ax)/dx:Infinity,dy>0?(y+h-ay)/dy:dy<0?(y-ay)/dy:Infinity];const t=Math.min(...ts);if(t>=0&&t<1){ax+=t*dx;ay+=t*dy;}}}
 let lo=0,hi=1,dx=bx-ax,dy=by-ay;for(const [p,q] of [[-dx,ax-cx],[dx,cx+cw-ax],[-dy,ay-cy],[dy,cy+ch-ay]]){if(p===0){if(q<0)return null;}else{const t=q/p;if(p<0)lo=Math.max(lo,t);else hi=Math.min(hi,t);}}return lo>hi?null:geo.point([ax+lo*dx,ay+lo*dy]);};
 const rails=relevant.map(({o,i,t})=>{const starts=(t.leaders||[]).map(j=>entry(cfg.strokes[j])).filter(Boolean);const unique=starts.filter((p,j)=>!starts.slice(0,j).some(q=>Math.hypot(p[0]-q[0],p[1]-q[1])<1));const p=unique.length?unique.reduce((a,p)=>[a[0]+p[0]/unique.length,a[1]+p[1]/unique.length],[0,0]):geo.point(t.points.find(geo.inside));const side=p[0]<250?'left':'right';return {o,i,t,starts:unique,side,x:side==='left'?50:450,y:Math.max(48,Math.min(552,p[1]))};});
 // Spread controls on each side without changing their anatomical endpoints.
 for(const side of ['left','right']){const r=rails.filter(x=>x.side===side).sort((a,b)=>a.y-b.y);for(let j=1;j<r.length;j++)r[j].y=Math.max(r[j].y,r[j-1].y+61);if(r.length&&r.at(-1).y>554){r.at(-1).y=554;for(let j=r.length-2;j>=0;j--)r[j].y=Math.min(r[j].y,r[j+1].y-61);}}
 const selectedRail=rails.find(r=>r.i===index),showTarget=!!selected&&(practice||labels);
 const endpoints=showTarget?selected.points.filter(geo.inside).map(geo.point):[];
 const rail=selectedRail||{x:50,y:300,side:'left'};
 const primary=endpoints[0]||null;
 const label=practice?(systemQuestion?(answered?s.name+' system · '+s.organs[index]?.[0]:'Name the system for the marked anatomy'):(answered?s.organs[index]?.[0]:'Name the marked structure')):s.organs[index]?.[0];
 // Every visible study label connects to all its printed branches. Extensions
 // stay in the margin; the immutable textbook line completes the route.
 const shownRails=practice?rails.filter(r=>r.i===index):labels?rails:[];
 const connector=shownRails.map(r=>{const edge=r.side==='left'?geo.ox:geo.ox+cw*geo.scale;const elbow=edge+(r.side==='left'?-18:18);return r.starts.map(([x,y])=>`<path class="leader ${r.i===index?'active-leader':'inactive-leader'}" data-label-index="${r.i}" d="M ${r.x} ${r.y} L ${elbow} ${r.y} L ${elbow} ${y} L ${x} ${y}"/>`).join('');}).join('');
 const selectedTitle=showTarget?`<div class="selected-anatomy"><span class="selected-number">${practice&&!answered?'?':index+1}</span><div><strong>${esc(label)}</strong><small>${endpoints.length>1?'Paired or representative structures highlighted':detail?'Enlarged original · source resolution unchanged':'Follow the line to the target ring'}</small></div></div>`:`<div class="selected-anatomy neutral"><span>${practice?'Recall from the anatomy—no label clues.':'Original textbook artwork · interactive labels off.'}</span></div>`;
 return `<div class="anatomy-view ${detail?'detail-view':''} ${large?'large-view':''}"><div class="anatomy-scene"><svg class="anatomy-drawing" viewBox="0 0 500 600" role="img" aria-label="${practice?'Textbook anatomy illustration with a target if applicable':esc(s.name+' anatomy, '+(detail?'enlarged detail':'anterior view'))}"><defs><clipPath id="${id}"><rect x="${geo.ox}" y="${geo.oy}" width="${cw*geo.scale}" height="${ch*geo.scale}"/></clipPath></defs><g clip-path="url(#${id})"><image data-anatomy-image="${file}" x="${geo.ox-cx*geo.scale}" y="${geo.oy-cy*geo.scale}" width="${cfg.size[0]*geo.scale}" height="${cfg.size[1]*geo.scale}"/>${cfg.clear.map(([x,y,w,h])=>`<rect x="${geo.ox+(x-cx)*geo.scale}" y="${geo.oy+(y-cy)*geo.scale}" width="${w*geo.scale}" height="${h*geo.scale}" fill="white"/>`).join('')}</g>${connector}${endpoints.map(([x,y])=>`<circle class="target-halo" cx="${x}" cy="${y}" r="10"/><circle class="target-ring" cx="${x}" cy="${y}" r="5.5"/>`).join('')}</svg><div class="art-loading" role="status">Loading textbook illustration…</div>${practice?(selected?`<span class="anatomy-callout question" style="left:${rail.x/5}%;top:${rail.y/6}%" aria-hidden="true">${answered?'✓':'?'}</span>`:''):labels?rails.map(r=>`<button class="anatomy-callout ${r.i===index?'selected':''}" style="left:${r.x/5}%;top:${r.y/6}%" data-action="organ" data-index="${r.i}" aria-label="${esc(r.o[0])}" aria-pressed="${r.i===index}">${r.i+1}</button>`).join(''):''}</div>${selectedTitle}</div>`;
}
function plate(s,opts={}){
 const p=!!opts.practice,sex=opts.sex||state.sex,active=p?opts.target:state.organ,cfg=illustrations[fileFor(s,sex)],canDetail=active!==null&&!!cfg.targets[active]?.detail;
 const detail=canDetail&&(p?(state.session.detail??false):state.detail)&&(!p?state.labels:true);
 return `<div class="plate"><div class="plate-top"><span class="eyebrow">${p?'Visual recall':'Textbook specimen'} · ${s.figure===1?'01.4':'01.5'}</span>${!p?`<button class="btn small ${state.labels?'active':''}" data-action="labels" aria-pressed="${state.labels}">${icon('eye')} ${state.labels?'Labels on':'Labels off'}</button>`:'<span class="eyebrow">Anterior view</span>'}</div>${specimen(s,{...opts,sex,detail,answered:p&&!!state.session.feedback})}<div class="plate-bottom">${s.id==='reproductive'&&!p?`<div class="view-switch" aria-label="Reproductive anatomy view"><button data-action="sex" data-sex="male" class="${sex==='male'?'active':''}">Male</button><button data-action="sex" data-sex="female" class="${sex==='female'?'active':''}">Female</button></div>`:`<span>${detail?'Enlarged schematic detail':'Full body · anterior view'}</span>`}<div class="plate-view-controls">${canDetail&&(!p?state.labels:true)?`<button class="detail-toggle" data-action="detail" aria-pressed="${detail}" aria-label="${detail?'Return to full-body view':'Enlarge the selected structure'}">${icon(detail?'back':'expand')} ${detail?'Full body':'Detail'}</button>`:''}<button class="detail-toggle" data-action="zoom" aria-label="Open large anatomy view">${icon('expand')}</button></div></div><div class="image-credit">Images: <a href="https://openstax.org/details/books/anatomy-and-physiology-2e" target="_blank" rel="noopener">OpenStax, Anatomy and Physiology 2e</a> · © Rice University · <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener">CC BY-NC-SA 4.0</a></div></div>`;
}
function showAnatomyZoom(){const p=state.view==='session',ss=state.session,q=p?ss.questions[ss.index]:null,s=p?sys(q.system):current(),target=p?q.organ:state.organ,sex=p?q.sex:state.sex;const cfg=illustrations[fileFor(s,sex)],canDetail=target!==null&&!!cfg.targets[target]?.detail;const detail=canDetail&&(p?(ss.detail??false):state.detail)&& (p||state.labels);showModal(p&&!ss.feedback?'Anatomy detail':`${s.name} · ${detail?'structure detail':'full body'}`,`<div class="plate expanded-anatomy">${specimen(s,{practice:p,target,sex,detail,systemQuestion:p&&q.type==='identify',answered:p&&!!ss.feedback,large:true})}</div><p>${p&&!ss.feedback?'The target ring identifies the structure; the question marker stays outside the anatomy.':'Select a numbered callout to explore another visible structure.'}</p>`);$('#modal').dataset.anatomy='true';hydrateAnatomy();}
function atlas(){const s=current();const visible=s.organs.map((o,i)=>({o,i})).filter(({o})=>s.id!=='reproductive'||o[4]===state.sex);return `<div class="intro"><div><div class="eyebrow">Chapter 01 · The human body</div><h1>Your body. Eleven systems.</h1><p>Explore the structures. Connect their functions.</p></div><div class="section-index"><strong>${String(systems.indexOf(s)+1).padStart(2,'0')}</strong> / 11</div></div><section class="atlas-grid fade-in" style="--accent:${s.color}" aria-label="${s.name} system">${plate(s)}<div class="details"><div class="system-heading"><div class="system-swatch"></div><div><h2>${s.name}</h2><p>${s.tag}</p></div></div><div class="segmented" role="tablist" aria-label="System information"><button role="tab" aria-selected="${state.tab==='structures'}" data-action="tab" data-tab="structures" class="${state.tab==='structures'?'active':''}">Structures</button><button role="tab" aria-selected="${state.tab==='functions'}" data-action="tab" data-tab="functions" class="${state.tab==='functions'?'active':''}">Functions</button><button role="tab" aria-selected="${state.tab==='connections'}" data-action="tab" data-tab="connections" class="${state.tab==='connections'?'active':''}">Connections</button></div><div role="tabpanel">${state.tab==='structures'?`<div class="structure-list">${visible.map(({o,i})=>`<button class="organ-row ${state.organ===i?'selected':''}" data-action="organ" data-index="${i}" aria-pressed="${state.organ===i}"><span class="organ-no">${i+1}</span><span class="organ-text">${o[0]}</span><span class="arrow">↗</span></button>`).join('')}</div><p class="organ-explainer"><strong>${s.organs[state.organ][0]}.</strong> ${s.organs[state.organ][3]}</p>`:state.tab==='functions'?`<ul class="function-list">${s.functions.map(f=>`<li>${f}</li>`).join('')}</ul><div class="explain-box"><h3>How it works</h3><p>${s.how}</p></div>`:`<div class="explain-box"><h3>Keep the distinction</h3><p>${s.confusion}</p></div><div class="explain-box"><h3>Part of a bigger picture</h3><p>${s.summary}</p></div>`}<details class="extra"><summary>Beyond the essentials</summary><p>${s.extra}</p></details></div><div class="memory-card"><div class="eyebrow">${icon('spark')} Memory cue</div><h3>${s.cue}</h3><p>${s.memory}</p></div><div class="detail-actions"><button class="btn primary" data-action="start" data-mode="focused">Practice this system ${icon('arrow')}</button><button class="btn ghost" data-action="source" aria-label="View original textbook figure">${icon('book')}</button></div></div></section><div class="bottom-strip"><div><h3>Recognition is the beginning. Recall is the goal.</h3><p>A mixed session connects names, structures, and functions.</p></div><button class="btn" data-action="start" data-mode="mixed">Start session ${icon('play')}</button></div>`;}
const modes=[['identify','eye','Name the system','Name the system that includes the marked anatomy.','Visual → name'],['structures','target','Label the anatomy','Name the structure at the highlighted point.','Structure → label'],['functions','layers','Know the function','Connect a physiological job with its organ system.','Function → system'],['connections','link','Untangle the mix-ups','Distinguish systems that work together or share organs.','Compare → connect'],['explain','book','Explain it back','Write the function in your own words, then check the essentials.','Explain → reflect'],['mixed','spark','Mixed recall','Move between identification, labeling, and function questions.','All three skills']];
function practice(){return `<div class="intro"><div><div class="eyebrow">Active recall</div><h1>Make it stick.</h1><p>Retrieve first. Check your thinking. Come back later.</p></div></div><div class="session-banner fade-in"><div><div class="eyebrow">Your next session</div><h2>${dueItems().length?'A little review goes a long way.':'Meet all eleven. Then test yourself.'}</h2><p>${dueItems().length?`${dueItems().length} skill areas are ready for review. Your session prioritizes those before new material.`:'Start with a mixed session, or focus on one kind of knowledge below.'}</p></div><button class="btn primary" data-action="start" data-mode="today">Start today’s session ${icon('arrow')}</button></div><div class="session-settings"><label for="difficulty">Answer style</label><select id="difficulty"><option value="recall" ${state.difficulty==='recall'?'selected':''}>Type from memory</option><option value="recognition" ${state.difficulty==='recognition'?'selected':''}>Choose from options</option></select><label for="length">Session length</label><select id="length"><option value="11" ${state.length===11?'selected':''}>11 questions</option><option value="22" ${state.length===22?'selected':''}>22 questions</option></select></div><div class="mode-grid">${modes.map(([id,ic,title,desc,foot],i)=>`<button class="mode-card fade-in" style="animation-delay:${i*45}ms" data-action="start" data-mode="${id}"><span class="mode-icon">${icon(ic)}</span><h3>${title}</h3><p>${desc}</p><span class="mode-footer">${foot}<span>↗</span></span></button>`).join('')}</div><div class="bottom-strip"><div><h3>Hints are help, not independent recall.</h3><p>Assisted answers stay in review. Spelling feedback is separate from anatomy knowledge.</p></div><button class="link-btn" data-action="guide">How progress works</button></div>`;}
// Use representative targets with an unambiguous system association. Shared
// endocrine/reproductive organs are assessed by function in the comparison bank.
function makeQuestion(s,type,orgIndex){if(type==='identify'){
 const sex=s.id==='reproductive'?(Math.random()<.5?'male':'female'):'male';
 const organ=s.id==='reproductive'?(sex==='male'?1:3):({endocrine:1,lymphatic:1,respiratory:2}[s.id]??0);
 return {type,system:s.id,skill:'name',organ,answer:s.name,q:'Which organ system includes the marked anatomy?',instruction:s.id==='integumentary'?'Follow the pointer to the outer covering at the shoulder. Name its organ system.':'Follow the pointer to the ring. Name the organ system, not the individual structure.',why:s.organs[organ][0]+' belongs to the '+s.name.toLowerCase()+' system. '+s.summary,hint:s.functions[0],options:shuffle([s.name,...shuffle(systems.filter(x=>x.id!==s.id)).slice(0,3).map(x=>x.name)]),sex};
 }
 if(type==='structures'){const oi=orgIndex??Math.floor(Math.random()*s.organs.length),o=s.organs[oi];const other=[...new Set([...s.organs.filter(x=>x[0]!==o[0]).map(x=>x[0]),...shuffle(systems.filter(x=>x.id!==s.id)).flatMap(x=>x.organs.map(z=>z[0]))])].filter(n=>n!==o[0]);return {type,system:s.id,skill:'structures',organ:oi,answer:o[0],q:'Name the structure marked by the ring.',instruction:'Follow the pointer to its endpoint. Give the structure name, not the organ system.',why:o[3],hint:o[3],options:shuffle([o[0],...shuffle(other).slice(0,3)]),sex:o[4]||'male'};}
 if(type==='functions')return {type,system:s.id,skill:'functions',answer:s.name,q:'Which organ system does this describe?',description:s.summary,why:s.how,hint:`A representative structure: ${s.organs[0][0].toLowerCase()}.`,options:shuffle([s.name,...shuffle(systems.filter(x=>x.id!==s.id)).slice(0,3).map(x=>x.name)])};
 if(type==='explain')return {type,system:s.id,skill:'functions',answer:s.name,q:`What does the ${s.name.toLowerCase()} system do?`,why:s.how,rubric:s.functions,hint:s.cue};
}
function start(mode,custom){
 let qs=[];const ids=shuffle(systems);const n=mode==='focused'?Math.max(6,current().organs.length+2):state.length;
 if(custom){qs=custom.map(q=>({...q,options:q.options?shuffle(q.options):undefined}));}
 else if(mode==='connections'){qs=shuffle(connections).slice(0,n).map(c=>({...c,type:'connections',skill:'functions',options:shuffle(c.options),hint:'Focus on the specific job in the question, not every system involved.'}));}
 else if(mode==='focused'){const s=current();qs=[makeQuestion(s,'identify'),...shuffle(s.organs.map((o,i)=>makeQuestion(s,'structures',i))),makeQuestion(s,'functions')];}
 else if(mode==='today'){
  const due=shuffle(dueItems()).slice(0,n);qs=due.map(d=>makeQuestion(sys(d.id),{name:'identify',structures:'structures',functions:'functions'}[d.skill]));
  while(qs.length<n){const s=ids[qs.length%11];qs.push(makeQuestion(s,['identify','structures','functions'][qs.length%3]));}
 }else{for(let i=0;i<n;i++){const s=ids[i%11],type=mode==='mixed'?['identify','structures','functions'][i%3]:mode;qs.push(makeQuestion(s,type));}}
 state.session={mode,questions:qs,index:0,results:[],feedback:null,hint:false,draft:'',revealed:false,finished:false};state.view='session';render();window.scrollTo({top:0,behavior:'instant'});
}
function sessionView(){const ss=state.session;if(!ss)return practice();if(ss.finished)return summary();const q=ss.questions[ss.index],s=sys(q.system);const choices=q.type==='connections'||(state.difficulty==='recognition'&&q.type!=='explain');return `<div class="quiz-progress"><button class="btn ghost small" data-action="view" data-view="practice" aria-label="Leave session">${icon('back')}</button><div class="meter"><span style="width:${ss.index/ss.questions.length*100}%"></span></div><span class="small">${ss.index+1} / ${ss.questions.length}</span></div><div class="quiz-layout fade-in">${['identify','structures'].includes(q.type)?plate(s,{practice:true,target:q.organ,sex:q.sex,systemQuestion:q.type==='identify'}):`<div class="concept-plate"><div class="concept-symbol">${q.type==='connections'?'⇄':q.type==='explain'?'“':'↗'}</div><div class="eyebrow">${q.type==='connections'?'Structure meets function':q.type==='explain'?'In your own words':'Read the function'}</div><h3>${q.description|| (q.type==='explain'?s.name:'Different jobs. One body.')}</h3><p>${q.type==='connections'?'Read carefully. Several systems may cooperate, but each question asks about a specific role.':q.type==='explain'?'Try a short explanation before checking the model answer.':'Identify the system from what it does.'}</p></div>`}<div class="quiz-panel"><div class="eyebrow">${q.type==='identify'?'01 / Identify':q.type==='structures'?'02 / Label':q.type==='functions'?'03 / Connect':q.type==='explain'?'Explain & compare':'Distinguish & apply'}${q.type==='structures'?` · ${s.name}`:''}</div><h2>${q.q}</h2>${q.instruction?`<p class="question-instruction">${esc(q.instruction)}</p>`:''}${q.type==='explain'?`<form id="answer-form"><label class="small" for="answer">Your explanation</label><textarea class="answer-input" id="answer" rows="4" placeholder="This system…" ${ss.revealed?'readonly':''}>${esc(ss.draft)}</textarea>${!ss.revealed?'<button class="btn primary" type="submit">Compare with the essentials</button>':''}</form>${ss.revealed?`<div class="feedback"><h3>Check your explanation</h3><ul class="function-list">${q.rubric.map(r=>`<li>${r}</li>`).join('')}</ul><p>${q.why}</p><p class="small">Self-assessment is saved as review, not independently verified recall.</p><div class="answer-actions"><button class="btn primary" data-action="self" data-ok="true">I covered these ideas</button><button class="btn" data-action="self" data-ok="false">I missed something</button></div></div>`:''}`:choices?`<div class="choice-list">${q.options.map((a,i)=>`<button class="choice ${ss.feedback?(a===q.answer?'correct':a===ss.feedback.given?'wrong':''):''}" data-action="answer" data-answer="${esc(a)}" ${ss.feedback?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${a}</span></button>`).join('')}</div>`:`<form id="answer-form"><label class="small" for="answer">${q.type==='structures'?'Structure name':'System name'}</label><input class="answer-input" id="answer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Type your answer…" value="${esc(ss.draft)}" ${ss.feedback?'readonly':''}><div class="answer-actions">${!ss.feedback?'<button class="btn primary" type="submit">Check answer</button>':''}</div></form>`}${!ss.feedback&&!ss.revealed?`<div class="answer-actions" style="margin-top:13px"><button class="link-btn" data-action="hint">${ss.hint?'Hint shown':'Need a hint?'}</button>${q.type!=='explain'?'<button class="link-btn" data-action="reveal">Show answer</button>':''}</div>`:''}${ss.hint&&!ss.feedback?`<p class="hint">${q.hint} <span class="small">This answer will count as assisted.</span></p>`:''}${ss.feedback?feedbackHTML(q,ss.feedback):''}</div></div>`;}
function normalize(s){return s.toLowerCase().trim().replace(/[^a-z\s]/g,'').replace(/\b(the|system)\b/g,'').replace(/\s+/g,' ').trim();}
function distance(a,b){let v=Array.from({length:b.length+1},(_,i)=>i);for(let i=0;i<a.length;i++){let u=[i+1];for(let j=0;j<b.length;j++)u.push(Math.min(u[j]+1,v[j+1]+1,v[j]+(a[i]!==b[j]?1:0)));v=u;}return v[b.length];}
function evaluate(given,answer,q){const g=normalize(given),a=normalize(answer);const synonyms={cardiovascular:['circulatory','cardiovascular circulatory'],lymphatic:['lymphatic immune','lymphatic and immune'],reproductive:['male reproductive','female reproductive'],'urinary bladder':['bladder'],kidneys:['kidney'],bones:['bone'],lungs:['lung'],tendons:['tendon'],'skeletal muscles':['skeletal muscle'],testes:['testis','testicles'],'adrenal glands':['adrenals','adrenal gland'],ovaries:['ovary'],'lymph nodes':['lymph node'], 'mammary glands':['mammary gland']};if(g===a||(synonyms[a]||[]).includes(g))return {ok:true,spelling:false};
 const known=systems.map(s=>normalize(s.name)).concat(systems.flatMap(s=>s.organs.map(o=>normalize(o[0]))),['ureter','ureters','urethra']);
 if(!known.includes(g)&&g.length>=5&&a.length>=6&&distance(g,a)<= (a.length>=10?2:1))return {ok:true,spelling:true};return {ok:false,spelling:false};}
function submitAnswer(given,reveal=false){const ss=state.session;if(!ss||ss.feedback)return;const q=ss.questions[ss.index];if(!given.trim()&&!reveal){toast('Try an answer, or choose “Show answer.”');return;}const result=reveal?{ok:false,spelling:false}:q.type==='connections'?{ok:given===q.answer,spelling:false}:evaluate(given,q.answer,q);const assisted=ss.hint||reveal;ss.feedback={...result,given,assisted,reveal};ss.draft=given;record(q,result.ok,assisted);ss.results.push({q,ok:result.ok,assisted,spelling:result.spelling});render();if(result.ok&&!assisted)burst();requestAnimationFrame(()=>$('.feedback')?.scrollIntoView({behavior:saved.settings.motion?'smooth':'instant',block:'nearest'}));}
function feedbackHTML(q,f){return `<div class="feedback ${f.ok?'':'wrong'}" role="status"><h3>${f.reveal?'Answer revealed':f.ok?(f.spelling?'Anatomy right. Check the spelling.':f.assisted?'Correct—with a little help.':'You’ve got it.'):'Let’s separate the ideas.'}</h3><p><strong>${q.answer}</strong>${f.spelling?` is the correct spelling. Your identification counts.`:'.'} ${q.why}</p>${!f.ok&&!f.reveal&&sys(q.system)&&systems.some(s=>normalize(s.name)===normalize(f.given))?`<p style="margin-top:8px">${sys(q.system).confusion}</p>`:''}${f.assisted?'<p style="margin-top:8px" class="small">Saved for review; not counted as independent recall.</p>':''}<button class="btn primary" data-action="next">${state.session.index+1===state.session.questions.length?'See session results':'Next question'} ${icon('arrow')}</button></div>`;}
function next(){const ss=state.session;ss.index++;ss.feedback=null;ss.hint=false;ss.draft='';ss.revealed=false;delete ss.detail;if(ss.index>=ss.questions.length){ss.finished=true;saved.sessions.unshift({at:Date.now(),total:ss.results.length,independent:ss.results.filter(r=>r.ok&&!r.assisted&&!r.self).length});saved.sessions=saved.sessions.slice(0,30);persist();}render();window.scrollTo({top:0,behavior:'instant'});}
function summary(){const ss=state.session;const independent=ss.results.filter(r=>r.ok&&!r.assisted&&!r.self).length;const review=ss.results.filter(r=>!r.ok||r.assisted||r.self);const pct=Math.round(independent/ss.results.length*100);return `<section class="summary fade-in"><div class="score-ring" style="--score:${pct}%"><span>${independent}<small>of ${ss.results.length} independent</small></span></div><div class="eyebrow">Session complete</div><h1 style="margin-top:10px">${review.length?'You found your next steps.':'That’s a strong first recall.'}</h1><p>${review.length?'These items deserve another look. A corrected answer is progress; remembering it later is the next goal.':'Come back on another day to check what stayed with you. One session is a start, not a claim of permanent mastery.'}</p>${review.length?`<div class="review-list">${review.map(r=>`<div><span>${sys(r.q.system).name} · ${r.q.skill==='name'?'Identification':r.q.skill==='structures'?'Structures':'Functions'}</span><span class="muted">${r.self?'Self-assessed':r.assisted?'Assisted':'Review'}</span></div>`).join('')}</div>`:''}<div class="answer-actions" style="justify-content:center">${review.length?'<button class="btn primary" data-action="retry">Practice these again</button>':''}<button class="btn ${review.length?'':'primary'}" data-action="view" data-view="progress">View progress</button><button class="btn ghost" data-action="view" data-view="atlas">Back to atlas</button></div><p class="small" style="margin-bottom:0">${storageAvailable?'Progress is saved in this browser.':'Progress is available for this tab only.'}</p></section>`;}
function progress(){const all=systems.flatMap(s=>['name','structures','functions'].map(k=>stat(s.id,k)));const repeated=all.filter(s=>s.days.length>=2&&s.lastResult==='independent').length;const attempted=all.filter(s=>s.attempts).length;return `<div class="intro"><div><div class="eyebrow">Your learning record</div><h1>Evidence, not just a score.</h1><p>Identification, structures, and functions are tracked separately.</p></div><button class="btn primary" data-action="start" data-mode="today">Review ${icon('arrow')}</button></div><div class="stats-row"><div class="stat"><div class="eyebrow">Skills practiced</div><strong>${attempted}<span class="muted" style="font-size:18px"> / 33</span></strong><small>Three skills × eleven systems</small></div><div class="stat"><div class="eyebrow">Recalled on 2+ days</div><strong>${repeated}</strong><small>Independent answers, separate days</small></div><div class="stat"><div class="eyebrow">Ready for review</div><strong>${dueItems().length}</strong><small>Previously practiced skill areas</small></div></div><div class="table-wrap"><table class="progress-table"><thead><tr><th>Organ system</th><th>Identification</th><th>Structures</th><th>Functions</th><th></th></tr></thead><tbody>${systems.map(s=>`<tr><td>${s.name}</td>${['name','structures','functions'].map(k=>{const [label,cl]=skillLabel(s.id,k);return `<td><span class="skill-status ${cl}">${cl==='recalled'?'✓ ':''}${label}</span></td>`;}).join('')}<td><button class="link-btn" data-action="system" data-id="${s.id}">Study</button></td></tr>`).join('')}</tbody></table></div><div class="bottom-strip"><div><h3>Learning is checked across days.</h3><p>Independent answers return in 1, 3, 7, then 14 days. Missed or assisted items return sooner.</p><p>Skill status summarizes sampled questions, not every organ in that system.</p></div><button class="link-btn" data-action="guide">Read the method</button></div><div class="session-settings"><span>Progress is local to this browser; it does not sync between devices.</span><button class="link-btn" data-action="reset-confirm">Reset progress</button></div>`;}
function showModal(title,body){const d=$('#modal');delete d.dataset.anatomy;d.innerHTML=`<div class="modal-top"><h2>${title}</h2><button class="btn ghost small" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function credits(){showModal('Textbook sources & credits',`<p>Illustrations: <strong>OpenStax, Anatomy and Physiology 2e</strong>, Chapter 1, §1.2, Figures 1.4–1.5, printed pages 12–13. © 2026 Rice University, as stated in your uploaded edition.</p><p><a href="https://openstax.org/details/books/anatomy-and-physiology-2e" target="_blank" rel="noopener">Access for free at openstax.org.</a></p><p>The original textbook image files remain available below. Interactive views display the original image pixels, including the textbook’s printed pointers. No erasing, reconstruction, or AI sharpening is applied. External numbered callouts follow the existing printed pointers; target rings and optional enlarged crops are added separately. Tiny details remain schematic; consult the original figures when needed.</p><p>Textbook-derived content and these educational adaptations are shared under <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener">CC BY-NC-SA 4.0</a>. No endorsement by OpenStax or Rice University is implied.</p><p>Chapter essentials follow the supplied textbook overview. “Beyond the essentials” contains introductory explanations beyond the figure captions. This studio is an organ-systems study aid, not a replacement for the rest of Chapter 1.</p><div class="answer-actions"><button class="btn" data-action="original" data-figure="1">Figure 1.4</button><button class="btn" data-action="original" data-figure="2">Figure 1.5</button></div>`);}
function settings(){showModal('Make the studio yours',`<label><input type="checkbox" id="motion" ${saved.settings.motion?'checked':''}> Animated transitions and reveal effects</label><label><input type="checkbox" id="focus" ${saved.settings.focus?'checked':''}> Quiet the effects during recall sessions</label><p>Your device’s reduced-motion preference is always respected.</p><p>Progress and preferences are saved in this browser. There is no cross-device synchronization.</p><div class="answer-actions"><button class="btn primary" data-action="save-settings">Save preferences</button><button class="btn" data-action="guide">Study guide</button></div>`);}
function guide(){showModal('A short route to stronger recall',`<p><strong>1. Explore.</strong> Choose a system, select its structures, and read their functions. Numbered callouts sit outside the anatomy and correspond to the structure list. A thin connector leads to a small target ring. Selecting a small structure opens its enlarged detail; Full body restores the overview. Labels off removes all callouts and returns to the full-body illustration. The optional male/female views both belong to the reproductive system.</p><p><strong>2. Retrieve.</strong> Open the Recall lab. Start with choices if needed, then switch to typing. In a mixed session, the kind of question changes.</p><p><strong>3. Correct.</strong> Feedback explains the specific job. Close spellings may earn identification credit, but different anatomical terms are not interchangeable.</p><p><strong>4. Return.</strong> Review on another day. Independent correct answers are scheduled after roughly 1, 3, 7, and 14 days as separate-day recalls accumulate. Missed, self-assessed, or assisted items return after 10 minutes. These intervals are practical defaults, not a guarantee of retention.</p><p><strong>What the progress labels mean.</strong> “Recalled today” means an independent correct answer today, unless a later attempt needs review. Older successful attempts are labeled “Recalled independently.” “Recalled on 2+ days” requires independent answers on separate dates. Structure progress summarizes a sample of structures; it does not certify every label.</p><p><strong>Chapter 1 target.</strong> Name all eleven systems, recognize representative organs, and state their major functions. Then explain a simple connection between systems.</p>`);}
function burst(){if(!saved.settings.motion||saved.settings.focus||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const f=$('.feedback');if(!f)return;f.style.position='relative';for(let i=0;i<9;i++){const e=document.createElement('i');e.className='session-complete-spark';e.style.cssText=`top:20px;right:20px;--x:${Math.cos(i)*60}px;--y:${Math.sin(i)*60}px`;f.append(e);setTimeout(()=>e.remove(),900);}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;switch(a){
 case 'view':setView(b.dataset.view);break;
 case 'system':selectSystem(b.dataset.id);break;
 case 'tab':state.tab=b.dataset.tab;render();break;
 case 'organ':{const zoom=$('#modal').open&&$('#modal').dataset.anatomy==='true';state.organ=Number(b.dataset.index);state.labels=true;if(current().id==='reproductive')state.sex=current().organs[state.organ][4];state.detail=false;render();if(zoom)showAnatomyZoom();break;}
 case 'sex':state.sex=b.dataset.sex;state.organ=current().organs.findIndex(o=>o[4]===state.sex);state.detail=false;render();break;
 case 'labels':state.labels=!state.labels;if(!state.labels)state.detail=false;render();break;
 case 'detail':if(state.view==='session')state.session.detail=!(state.session.detail??false);else state.detail=!state.detail;render();break;
 case 'start':start(b.dataset.mode);break;
 case 'answer':submitAnswer(b.dataset.answer);break;
 case 'next':next();break;
 case 'hint':state.session.draft=$('#answer')?.value||'';state.session.hint=true;render();break;
 case 'reveal':submitAnswer('',true);break;
 case 'self':{const ss=state.session,q=ss.questions[ss.index],ok=b.dataset.ok==='true';record(q,ok,ss.hint,true);ss.results.push({q,ok,assisted:ss.hint,self:true});next();break;}
 case 'retry':{const qs=state.session.results.filter(r=>!r.ok||r.assisted||r.self).map(r=>r.q);start('retry',shuffle(qs));break;}
 case 'settings':settings();break;
 case 'save-settings':saved.settings.motion=$('#motion').checked;saved.settings.focus=$('#focus').checked;persist();$('#modal').close();render();toast('Preferences saved.');break;
 case 'guide':guide();break;
 case 'credits':credits();break;
 case 'source':case 'original':{const f=Number(b.dataset.figure||current().figure);showModal(`Original textbook · Figure 1.${f===1?'4':'5'}`,`<img src="assets/figure-${f}.png" alt="Original OpenStax organ systems figure with printed labels and functions"><p>© 2026 Rice University / OpenStax. CC BY-NC-SA 4.0. <a href="https://openstax.org/details/books/anatomy-and-physiology-2e" target="_blank" rel="noopener">Access for free at openstax.org.</a></p>`);break;}
 case 'zoom':showAnatomyZoom();break;
 case 'close':$('#modal').close();break;
 case 'leave':$('#modal').close();state.session=null;state.view=b.dataset.view;render();break;
 case 'reset-confirm':showModal('Reset your learning record?',`<p>This deletes the progress saved in this browser. Your display preferences will stay.</p><div class="answer-actions"><button class="btn" data-action="close">Keep my progress</button><button class="btn primary" data-action="reset">Reset progress</button></div>`);break;
 case 'reset':saved.progress={};saved.sessions=[];persist();$('#modal').close();render();toast('Progress reset.');break;
}});
document.addEventListener('change',e=>{if(e.target.id==='difficulty')state.difficulty=e.target.value;if(e.target.id==='length')state.length=Number(e.target.value);});
document.addEventListener('submit',e=>{if(e.target.id!=='answer-form')return;e.preventDefault();const ss=state.session;if(!ss||ss.feedback)return;const q=ss.questions[ss.index];ss.draft=$('#answer').value;if(q.type==='explain'){if(!ss.draft.trim()){toast('Try a short explanation first.');return;}ss.revealed=true;render();}else submitAnswer(ss.draft);});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
if(document.modelContext?.registerTool){const controller=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:controller.signal})).catch(()=>{});}catch{}};
 register({name:'read_learning_progress',title:'Read learning progress',description:'Read browser-local organ system progress without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({systems:systems.map(s=>({name:s.name,identification:skillLabel(s.id,'name')[0],structures:skillLabel(s.id,'structures')[0],functions:skillLabel(s.id,'functions')[0]})),due:dueItems().length})});
 register({name:'open_organ_system',title:'Open an organ system',description:'Navigate to a system in the study atlas. Does not complete practice or change progress.',inputSchema:{type:'object',properties:{system:{type:'string',enum:systems.map(s=>s.id)}},required:['system'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({system})=>{if(!sys(system))throw new Error('Unknown organ system.');if(state.session&&!state.session.finished)throw new Error('Finish or leave the active session first.');selectSystem(system);return {opened:system};}});
 window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
